package com.blog.service.impl; import com.blog.dto.CategoryDtos.*; import com.blog.entity.Category; import com.blog.exception.ApiExceptions.*; import com.blog.mapper.BlogMapper; import com.blog.repository.*; import com.blog.service.BlogServices.CategoryService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class CategoryServiceImpl implements CategoryService {private final CategoryRepository categories;private final PostRepository posts;private final BlogMapper mapper; public CategoryResponse create(CategoryRequest r){check(r.name());return mapper.category(categories.save(Category.builder().name(r.name()).description(r.description()).build()));} @Transactional(readOnly=true) public List<CategoryResponse> findAll(){return categories.findAll().stream().map(mapper::category).toList();} @Transactional(readOnly=true) public CategoryResponse findById(Long id){return mapper.category(category(id));} public CategoryResponse update(Long id,CategoryRequest r){var c=category(id);if(!c.getName().equalsIgnoreCase(r.name()))check(r.name());c.setName(r.name());c.setDescription(r.description());return mapper.category(c);} public void delete(Long id){if(posts.existsByCategoryId(id))throw new BadRequestException("Category is assigned to posts");categories.delete(category(id));} private Category category(Long id){return categories.findById(id).orElseThrow(()->new ResourceNotFoundException("Category not found"));}private void check(String n){if(categories.existsByNameIgnoreCase(n))throw new BadRequestException("Category name already exists");}}
